import { test, expect } from '@playwright/test';

test.describe('Past Date Field Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/form');
  });

  test('should display error when submitting form with future date in past-date field', async ({ page }) => {
    // Set up intercept for form submission
    await page.route('**/api/submit-form', route => {
      route.abort('blockedbyclient');
    });

    // Fill in past date field with a future date
    const pastDateField = page.getByLabel('Past Date');
    await pastDateField.fill('2099-01-01');

    // Fill in other required fields
    const nameField = page.getByLabel('Full Name');
    await nameField.fill('John Doe');

    const emailField = page.getByLabel('Email');
    await emailField.fill('john@example.com');

    // Click submit button
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for validation error message to appear
    const errorMessage = page.getByText('Date cannot be in the future');
    await expect(errorMessage).toBeVisible();

    // Verify error message is associated with the correct field
    await expect(pastDateField).toHaveAttribute('aria-invalid', 'true');

    // Verify form was not submitted
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).not.toBeVisible();
  });

  test('should allow submission when past date field contains a valid past date', async ({ page }) => {
    // Set up intercept for successful form submission
    await page.route('**/api/submit-form', route => {
      route.continue();
    });

    // Fill in past date field with a valid past date
    const pastDateField = page.getByLabel('Past Date');
    await pastDateField.fill('2020-01-01');

    // Fill in other required fields
    const nameField = page.getByLabel('Full Name');
    await nameField.fill('Jane Smith');

    const emailField = page.getByLabel('Email');
    await emailField.fill('jane@example.com');

    // Click submit button
    const submitButton = page.getByRole('button', { name: /submit/i });
    await submitButton.click();

    // Wait for success message
    const successMessage = page.getByText('Form submitted successfully');
    await expect(successMessage).toBeVisible();

    // Verify form was submitted successfully
    const submitButton = page.getByRole('button', { name: /submit/i });
    await expect(submitButton).not.toBeDisabled();

    // Verify error message does not exist
    const errorMessage = page.getByText('Date cannot be in the future');
    await expect(errorMessage).not.toBeVisible();
  });
});
